#!/usr/bin/env python3
"""
Logic and methodology analyzer for LaTeX/Typst papers.

Checks: paragraph-level coherence, method justification,
literature review quality (A1/A3), cross-section logic chain (C3).
"""

import argparse
import re
import sys
from pathlib import Path

try:
    from parsers import extract_abstract, get_parser
except ImportError:
    sys.path.append(str(Path(__file__).parent))
    from parsers import extract_abstract, get_parser


TRANSITIONS = {
    "addition": {"furthermore", "moreover", "in addition", "additionally"},
    "contrast": {"however", "nevertheless", "in contrast", "conversely"},
    "cause": {"therefore", "consequently", "as a result", "thus"},
}


def _has_transition(text: str) -> bool:
    lowered = text.lower()
    return any(token in lowered for values in TRANSITIONS.values() for token in values)


def _needs_method_justification(text: str) -> bool:
    lowered = text.lower()
    if "we use" not in lowered and "we adopt" not in lowered:
        return False
    return not any(marker in lowered for marker in ["because", "due to", "to ", "for "])


# ── Literature review quality checks (A1, A3) ──────────────────

AUTHOR_ENUM_EN = re.compile(
    r"^(?:In \d{4}|.*?\(\d{4}\).*?(?:proposed|introduced|presented|developed|designed))",
    re.IGNORECASE,
)

GAP_KEYWORDS_EN = re.compile(
    r"\b(gap|limitation|however.*(?:no|not|few)|remains|lack|overlooked|"
    r"under-explored|open problem|yet to be|inadequate|insufficient)\b",
    re.IGNORECASE,
)


def _check_lit_review_enumeration(lines: list[str], start: int, end: int, parser) -> list[str]:
    """A1: Detect 3+ consecutive author/year enumeration patterns."""
    out: list[str] = []
    consecutive = 0
    streak_start = 0
    for line_no in range(start, min(end, len(lines)) + 1):
        raw = lines[line_no - 1].strip()
        if not raw or raw.startswith(parser.get_comment_prefix()):
            continue
        visible = parser.extract_visible_text(raw)
        if not visible:
            continue
        if AUTHOR_ENUM_EN.search(visible):
            if consecutive == 0:
                streak_start = line_no
            consecutive += 1
        else:
            if consecutive >= 3:
                out.extend(
                    [
                        f"% LIT-REVIEW (Lines {streak_start}-{line_no - 1}) "
                        "[Severity: Major] [Priority: P1]: "
                        f"Author/year enumeration detected ({consecutive} consecutive entries)",
                        "% Suggested: Reorganize by theme clusters with critical analysis.",
                        "% Rationale: Chronological/author enumeration weakens literature synthesis.",
                        "",
                    ]
                )
            consecutive = 0
    if consecutive >= 3:
        out.extend(
            [
                f"% LIT-REVIEW (Lines {streak_start}-{min(end, len(lines))}) "
                "[Severity: Major] [Priority: P1]: "
                f"Author/year enumeration detected ({consecutive} consecutive entries)",
                "% Suggested: Reorganize by theme clusters with critical analysis.",
                "% Rationale: Chronological/author enumeration weakens literature synthesis.",
                "",
            ]
        )
    return out


def _check_gap_derivation(lines: list[str], start: int, end: int, parser) -> list[str]:
    """A3: Check last 10 lines of Related Work for research gap language."""
    out: list[str] = []
    scan_start = max(start, end - 10)
    found_gap = False
    for line_no in range(scan_start, min(end, len(lines)) + 1):
        raw = lines[line_no - 1].strip()
        if not raw or raw.startswith(parser.get_comment_prefix()):
            continue
        visible = parser.extract_visible_text(raw)
        if visible and GAP_KEYWORDS_EN.search(visible):
            found_gap = True
            break
    if not found_gap:
        out.extend(
            [
                f"% LIT-REVIEW (Lines {scan_start}-{end}) "
                "[Severity: Major] [Priority: P1]: "
                "No research gap derivation found at end of Related Work",
                "% Suggested: Add explicit gap statement connecting literature to your contribution.",
                "% Rationale: Related Work should conclude by identifying gaps that motivate the study.",
                "",
            ]
        )
    return out


# ── Cross-section logic chain closure (C3) ──────────────────────

CONTRIBUTION_KEYWORDS_EN = re.compile(
    r"\b(we propose|we present|we introduce|our contribution|we design|we develop|"
    r"this paper proposes|this work presents|main contributions)\b",
    re.IGNORECASE,
)
ANSWER_KEYWORDS_EN = re.compile(
    r"\b(we have shown|we demonstrated|results show|results demonstrate|"
    r"experiments confirm|we have proposed|this paper has presented|"
    r"our experiments show|findings indicate|we have addressed)\b",
    re.IGNORECASE,
)

INTRO_BACKGROUND_RE = re.compile(
    r"\b(important|growing|widely used|demand|need|application|applications|"
    r"real-world|industry|practical|in recent years|increasingly)\b",
    re.IGNORECASE,
)
INTRO_PROBLEM_RE = re.compile(
    r"\b(problem|challenge|bottleneck|limitation|difficult|difficulty|issue|"
    r"expensive|costly|fails?|cannot|struggle|insufficient|inefficient)\b",
    re.IGNORECASE,
)
INTRO_PRIOR_RE = re.compile(
    r"\b(existing|previous|prior|earlier|current|traditional|state-of-the-art|"
    r"studies|literature|methods|approaches|however|nevertheless|recent work)\b",
    re.IGNORECASE,
)
TRIAD_PROBLEM_RE = re.compile(
    r"\b(problem|challenge|task|goal|objective|bottleneck|limitation|address)\b",
    re.IGNORECASE,
)
TRIAD_METHOD_RE = re.compile(
    r"\b(propose|present|introduce|design|develop|framework|method|approach|"
    r"model|mechanism|pipeline|strategy)\b",
    re.IGNORECASE,
)
TRIAD_RESULT_RE = re.compile(
    r"\b(result|results|improve|improvement|achieve|achieves|outperform|gain|"
    r"accuracy|f1|mae|mse|latency|throughput|benchmark|experiments show)\b",
    re.IGNORECASE,
)
TRIAD_CONTRIBUTION_RE = re.compile(
    r"\b(contribution|contributions|novel|we propose|we present|we introduce|"
    r"main contributions)\b",
    re.IGNORECASE,
)


def _section_visible_lines(
    lines: list[str], bounds: tuple[int, int], parser
) -> list[tuple[int, str]]:
    visible_lines: list[tuple[int, str]] = []
    comment_prefix = parser.get_comment_prefix()
    start, end = bounds
    for line_no in range(start, min(end, len(lines)) + 1):
        raw = lines[line_no - 1].strip()
        if not raw or raw.startswith(comment_prefix):
            continue
        visible = parser.extract_visible_text(raw)
        if visible:
            visible_lines.append((line_no, visible))
    return visible_lines


def _coverage_map(text: str) -> dict[str, bool]:
    lowered = text.lower()
    return {
        "problem": bool(TRIAD_PROBLEM_RE.search(lowered)),
        "method": bool(TRIAD_METHOD_RE.search(lowered)),
        "result": bool(TRIAD_RESULT_RE.search(lowered) or re.search(r"\d+(?:\.\d+)?%?", lowered)),
        "contribution": bool(TRIAD_CONTRIBUTION_RE.search(lowered)),
    }


def _check_introduction_funnel(
    lines: list[str], sections: dict[str, tuple[int, int]], parser
) -> list[str]:
    """Check whether introduction follows background -> problem -> prior work -> contribution."""
    out: list[str] = []
    if "introduction" not in sections:
        return out

    visible_lines = _section_visible_lines(lines, sections["introduction"], parser)
    if len(visible_lines) < 3:
        return out

    first_background = first_problem = first_prior = first_contribution = None
    for line_no, visible in visible_lines:
        lowered = visible.lower()
        if first_background is None and INTRO_BACKGROUND_RE.search(lowered):
            first_background = line_no
        if first_problem is None and INTRO_PROBLEM_RE.search(lowered):
            first_problem = line_no
        if first_prior is None and (
            INTRO_PRIOR_RE.search(lowered) or "\\cite{" in lines[line_no - 1] or "[" in visible
        ):
            first_prior = line_no
        if first_contribution is None and CONTRIBUTION_KEYWORDS_EN.search(lowered):
            first_contribution = line_no

    if first_contribution is None:
        return out

    if first_problem is None or first_contribution < first_problem:
        out.extend(
            [
                f"% INTRODUCTION (Line {first_contribution}) [Severity: Major] [Priority: P1]: "
                "Introduction may jump from background directly to contribution.",
                "% Suggested: Insert the unresolved technical bottleneck before presenting the method.",
                "% Rationale: Readers need the problem statement before the solution.",
                "",
            ]
        )

    if first_problem is not None and first_prior is None:
        out.extend(
            [
                f"% INTRODUCTION (Line {first_problem}) [Severity: Major] [Priority: P1]: "
                "Introduction states the problem but does not derive it from prior work limitations.",
                "% Suggested: Add a prior-work paragraph explaining what existing methods still fail to solve.",
                "% Rationale: The contribution should be motivated by concrete insufficiencies in the literature.",
                "",
            ]
        )
    elif (
        first_problem is not None
        and first_prior is not None
        and first_contribution is not None
        and first_prior > first_contribution
    ):
        out.extend(
            [
                f"% INTRODUCTION (Line {first_contribution}) [Severity: Major] [Priority: P1]: "
                "Contribution claim appears before prior-work insufficiencies are established.",
                "% Suggested: Reorder the introduction so literature limitations appear before the paper contribution.",
                "% Rationale: This preserves the background -> bottleneck -> prior effort -> contribution funnel.",
                "",
            ]
        )
    return out


def _check_tri_section_alignment(
    content: str, lines: list[str], sections: dict[str, tuple[int, int]], parser
) -> list[str]:
    """Check alignment among abstract, contribution source, and conclusion."""
    out: list[str] = []
    if "introduction" not in sections or "conclusion" not in sections:
        return out

    abstract_text = extract_abstract(content)
    if not abstract_text:
        return out

    intro_text = " ".join(
        text for _, text in _section_visible_lines(lines, sections["introduction"], parser)
    )
    conclusion_text = " ".join(
        text for _, text in _section_visible_lines(lines, sections["conclusion"], parser)
    )
    if not intro_text or not conclusion_text:
        return out

    coverage = {
        "abstract": _coverage_map(abstract_text),
        "contribution_source": _coverage_map(intro_text),
        "conclusion": _coverage_map(conclusion_text),
    }
    required_facets = {
        facet
        for facet in ("problem", "method", "result", "contribution")
        if sum(1 for sec in coverage.values() if sec[facet]) >= 2
    }

    mismatches: list[str] = []
    for section_name, section_coverage in coverage.items():
        missing = sorted(facet for facet in required_facets if not section_coverage[facet])
        if len(missing) >= 2 or (
            section_name in {"abstract", "conclusion"}
            and ("result" in missing or "contribution" in missing)
        ):
            mismatches.append(f"{section_name} missing {', '.join(missing)}")

    if coverage["contribution_source"]["contribution"]:
        if not coverage["abstract"]["contribution"]:
            mismatches.append("abstract missing contribution claim")
        if not coverage["conclusion"]["contribution"]:
            mismatches.append("conclusion missing contribution response")
    if coverage["abstract"]["method"] and not coverage["conclusion"]["result"]:
        mismatches.append("conclusion missing result evidence")

    if mismatches:
        out.extend(
            [
                "% LOGIC [Severity: Major] [Priority: P1]: "
                "Abstract, contribution claims, and conclusion may be misaligned.",
                f"% Observation: {'; '.join(mismatches)}.",
                "% Suggested: Make sure all three sections consistently state the problem, method, key results, and contribution.",
                "% Rationale: These sections should tell the same core story with different emphasis, not diverge.",
                "",
            ]
        )
    return out


def _check_cross_section_closure(
    lines: list[str], sections: dict[str, tuple[int, int]], parser
) -> list[str]:
    """C3: Verify that intro contributions are answered in conclusion."""
    out: list[str] = []
    if "introduction" not in sections or "conclusion" not in sections:
        return out

    intro_start, intro_end = sections["introduction"]
    concl_start, concl_end = sections["conclusion"]

    intro_claims = 0
    for line_no in range(intro_start, min(intro_end, len(lines)) + 1):
        raw = lines[line_no - 1].strip()
        if not raw or raw.startswith(parser.get_comment_prefix()):
            continue
        visible = parser.extract_visible_text(raw)
        if visible and CONTRIBUTION_KEYWORDS_EN.search(visible):
            intro_claims += 1

    if intro_claims == 0:
        return out

    concl_answers = 0
    for line_no in range(concl_start, min(concl_end, len(lines)) + 1):
        raw = lines[line_no - 1].strip()
        if not raw or raw.startswith(parser.get_comment_prefix()):
            continue
        visible = parser.extract_visible_text(raw)
        if visible and ANSWER_KEYWORDS_EN.search(visible):
            concl_answers += 1

    if concl_answers == 0:
        out.extend(
            [
                f"% LOGIC (Lines {concl_start}-{concl_end}) "
                "[Severity: Major] [Priority: P1]: "
                "[Script] Cross-section logic chain may be incomplete",
                f"% Observation: {intro_claims} contribution claim(s) in Introduction "
                "but no explicit answer language in Conclusion.",
                "% Suggested: Add statements that explicitly address each contribution.",
                "% Rationale: Conclusion should close the logic chain opened in Introduction.",
                "",
            ]
        )
    return out


def analyze(file_path: Path, section: str | None = None, cross_section: bool = False) -> list[str]:
    parser = get_parser(file_path)
    content = file_path.read_text(encoding="utf-8", errors="ignore")
    lines = content.split("\n")
    sections = parser.split_sections(content)

    if section:
        key = section.lower()
        if key not in sections:
            return [f"% ERROR [Severity: Critical] [Priority: P0]: Section not found: {section}"]
        ranges = [sections[key]]
    else:
        ranges = list(sections.values()) if sections else [(1, len(lines))]

    out: list[str] = []
    previous_visible = ""
    for start, end in ranges:
        for line_no in range(start, min(end, len(lines)) + 1):
            raw = lines[line_no - 1].strip()
            if not raw or raw.startswith(parser.get_comment_prefix()):
                continue

            visible = parser.extract_visible_text(raw)
            if not visible:
                continue

            if _needs_method_justification(visible):
                out.extend(
                    [
                        f"% METHODOLOGY (Line {line_no}) [Severity: Major] [Priority: P1]: "
                        "Method choice lacks explicit justification",
                        f"% Current: {visible}",
                        "% Suggested: Add rationale (e.g., efficiency/accuracy/reproducibility reasons).",
                        "% Rationale: Method statements should explain why the approach is selected.",
                        "",
                    ]
                )

            if (
                previous_visible
                and not _has_transition(visible)
                and re.search(
                    r"\b(problem|challenge|noisy|difficult)\b", previous_visible, re.IGNORECASE
                )
                and re.search(r"\b(we propose|we design|our method)\b", visible, re.IGNORECASE)
            ):
                out.extend(
                    [
                        f"% LOGIC (Line {line_no}) [Severity: Major] [Priority: P1]: "
                        "Potential logical jump between problem and solution",
                        f"% Current: {visible}",
                        "% Suggested: Add explicit transition (e.g., Therefore/Thus/To address this).",
                        "% Rationale: Strengthens paragraph-level coherence.",
                        "",
                    ]
                )

            previous_visible = visible

    # ── Section-level checks ───────────────────────────────────
    if sections:
        if not section and "introduction" in sections:
            out.extend(_check_introduction_funnel(lines, sections, parser))

        related_key = "related"
        if related_key in sections:
            r_start, r_end = sections[related_key]
            if not section or section.lower() == related_key:
                out.extend(_check_lit_review_enumeration(lines, r_start, r_end, parser))
                out.extend(_check_gap_derivation(lines, r_start, r_end, parser))

        if cross_section and not section:
            out.extend(_check_cross_section_closure(lines, sections, parser))
        if not section:
            out.extend(_check_tri_section_alignment(content, lines, sections, parser))

    if not out:
        out.append("% LOGIC/METHODOLOGY: No rule-based coherence issues detected.")
    return out


def main() -> int:
    cli = argparse.ArgumentParser(
        description="Logic and methodology analysis for LaTeX/Typst files"
    )
    cli.add_argument("file", type=Path, help="Target .tex/.typ file")
    cli.add_argument("--section", help="Section name to analyze")
    cli.add_argument(
        "--cross-section",
        action="store_true",
        help="Enable cross-section logic chain closure check",
    )
    args = cli.parse_args()

    if not args.file.exists():
        print(f"[ERROR] File not found: {args.file}", file=sys.stderr)
        return 1

    print("\n".join(analyze(args.file, args.section, args.cross_section)))
    return 0


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
"""
Long sentence analyzer (MVP) for LaTeX/Typst papers.
"""

import argparse
import re
import sys
from pathlib import Path

try:
    from parsers import get_parser
except ImportError:
    sys.path.append(str(Path(__file__).parent))
    from parsers import get_parser


CLAUSE_MARKERS = {"which", "that", "because", "although", "while", "whereas", "if", "when"}


def _count_words(text: str) -> int:
    return len(re.findall(r"\b[\w'-]+\b", text))


def _count_clauses(text: str) -> int:
    lowered = text.lower()
    marker_hits = sum(1 for marker in CLAUSE_MARKERS if re.search(rf"\b{marker}\b", lowered))
    comma_parts = max(0, text.count(","))
    return marker_hits + comma_parts


def _simplify_sentence(text: str) -> str:
    parts = [p.strip() for p in text.split(",") if p.strip()]
    if len(parts) <= 1:
        return text
    head = parts[0]
    tail = ". ".join(parts[1:])
    return f"{head}. {tail}."


def analyze(file_path: Path, section: str | None, max_words: int, max_clauses: int) -> list[str]:
    parser = get_parser(file_path)
    content = file_path.read_text(encoding="utf-8", errors="ignore")
    lines = content.split("\n")
    sections = parser.split_sections(content)

    if section:
        key = section.lower()
        if key not in sections:
            return [f"% ERROR [Severity: Critical] [Priority: P0]: Section not found: {section}"]
        ranges = [sections[key]]
    else:
        ranges = list(sections.values()) if sections else [(1, len(lines))]

    output: list[str] = []
    for start, end in ranges:
        for line_no in range(start, min(end, len(lines)) + 1):
            raw = lines[line_no - 1].strip()
            if not raw or raw.startswith(parser.get_comment_prefix()):
                continue
            visible = parser.extract_visible_text(raw)
            if not visible:
                continue
            for sentence in re.split(r"(?<=[.!?])\s+", visible):
                sent = sentence.strip()
                if not sent:
                    continue
                words = _count_words(sent)
                clauses = _count_clauses(sent)
                if words <= max_words and clauses <= max_clauses:
                    continue

                simplified = _simplify_sentence(sent)
                output.extend(
                    [
                        f"% LONG SENTENCE (Line {line_no}, {words} words, {clauses} clauses) "
                        "[Severity: Minor] [Priority: P2]",
                        f"% Original: {sent}",
                        f"% Suggested: {simplified}",
                        "% Rationale: Sentence exceeds complexity threshold, split for readability.",
                        "",
                    ]
                )
    if not output:
        output.append("% LONG SENTENCE: No sentences exceeded configured thresholds.")
    return output


def main() -> int:
    cli = argparse.ArgumentParser(description="Long sentence analysis for LaTeX/Typst files (MVP)")
    cli.add_argument("file", type=Path, help="Target .tex/.typ file")
    cli.add_argument("--section", help="Section name to analyze")
    cli.add_argument("--max-words", type=int, default=50, help="Max words per sentence")
    cli.add_argument("--max-clauses", type=int, default=3, help="Max clauses per sentence")
    args = cli.parse_args()

    if not args.file.exists():
        print(f"[ERROR] File not found: {args.file}", file=sys.stderr)
        return 1

    print("\n".join(analyze(args.file, args.section, args.max_words, args.max_clauses)))
    return 0


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
"""
Table Structure Checker - Validate three-line table compliance in LaTeX documents.

Usage:
    uv run python -B check_tables.py main.tex
    uv run python -B check_tables.py main.tex --fix-suggestions
    uv run python -B check_tables.py main.tex --json
"""

import argparse
import json
import re
import sys
from pathlib import Path


class TableChecker:
    """Validate LaTeX tables against the three-line (booktabs) standard."""

    LEVEL_ERROR = "ERROR"
    LEVEL_WARNING = "WARNING"
    LEVEL_INFO = "INFO"

    # Booktabs commands that define valid three-line rules
    VALID_RULES = {r"\toprule", r"\midrule", r"\bottomrule"}

    # Forbidden rule commands inside tabular body
    FORBIDDEN_RULES = {r"\hline", r"\vline", r"\cline"}

    def __init__(self, tex_file: str):
        self.tex_file = Path(tex_file).resolve()
        self.content = ""
        self.lines: list[str] = []
        self.issues: list[dict] = []

    def _load(self) -> bool:
        """Load the .tex file content."""
        if not self.tex_file.exists():
            self.issues.append(
                {
                    "line": 0,
                    "level": self.LEVEL_ERROR,
                    "priority": "P1",
                    "message": f"File not found: {self.tex_file}",
                    "category": "file",
                }
            )
            return False
        self.content = self.tex_file.read_text(encoding="utf-8", errors="replace")
        self.lines = self.content.split("\n")
        return True

    def check(self, fix_suggestions: bool = False) -> dict:
        """Run all table structure checks."""
        if not self._load():
            return self._result()

        self._check_booktabs_loaded()
        tables = self._find_table_environments()

        for table in tables:
            self._check_vertical_lines(table)
            self._check_rule_commands(table)
            self._check_caption_position(table)
            self._check_table_notes(table)
            self._check_number_precision(table)

        if fix_suggestions:
            for issue in self.issues:
                issue["fix"] = self._suggest_fix(issue)

        return self._result()

    def _result(self) -> dict:
        """Build result dictionary."""
        if not self.issues:
            status = "PASS"
        elif any(i["level"] == self.LEVEL_ERROR for i in self.issues):
            status = "FAIL"
        else:
            status = "WARNING"

        return {
            "status": status,
            "file": str(self.tex_file),
            "table_count": len(self._find_table_environments()),
            "issue_count": len(self.issues),
            "issues": self.issues,
        }

    def _check_booktabs_loaded(self) -> None:
        """Check if booktabs package is loaded."""
        has_booktabs = False
        for line in self.lines:
            stripped = line.split("%")[0]  # Ignore comments
            if re.search(r"\\usepackage(\[[^\]]*\])?\{.*booktabs.*\}", stripped):
                has_booktabs = True
                break
        if not has_booktabs and re.search(r"\\begin\{table\*?\}", self.content):
            self.issues.append(
                {
                    "line": 0,
                    "level": self.LEVEL_WARNING,
                    "priority": "P2",
                    "message": "booktabs package not loaded. Add \\usepackage{booktabs} for professional three-line tables.",
                    "category": "package",
                }
            )

    def _find_table_environments(self) -> list[dict]:
        """Find all table/table* environments with their line ranges."""
        tables = []
        pattern = re.compile(r"\\begin\{(table\*?)\}")
        end_pattern = re.compile(r"\\end\{(table\*?)\}")

        stack: list[dict] = []
        for i, line in enumerate(self.lines, 1):
            stripped = line.split("%")[0]
            for m in pattern.finditer(stripped):
                stack.append({"env": m.group(1), "start": i, "start_col": m.start()})
            for _m in end_pattern.finditer(stripped):
                if stack:
                    entry = stack.pop()
                    entry["end"] = i
                    entry["content"] = "\n".join(self.lines[entry["start"] - 1 : i])
                    tables.append(entry)

        return tables

    def _check_vertical_lines(self, table: dict) -> None:
        """Check for vertical lines in column specifications."""
        content = table["content"]
        # Find tabular column spec: \begin{tabular}{|c|c|c|}
        col_specs = re.findall(r"\\begin\{tabular\*?\}(?:\{[^}]*\})?\{([^}]+)\}", content)
        for spec in col_specs:
            if "|" in spec:
                self.issues.append(
                    {
                        "line": table["start"],
                        "level": self.LEVEL_ERROR,
                        "priority": "P1",
                        "message": f"Vertical lines detected in column spec: {{{spec}}}. Three-line tables must not have vertical lines.",
                        "category": "vertical_lines",
                    }
                )

        # Also check for \vline
        for i, line in enumerate(self.lines[table["start"] - 1 : table["end"]], table["start"]):
            stripped = line.split("%")[0]
            if r"\vline" in stripped:
                self.issues.append(
                    {
                        "line": i,
                        "level": self.LEVEL_ERROR,
                        "priority": "P1",
                        "message": "\\vline detected. Three-line tables must not have vertical lines.",
                        "category": "vertical_lines",
                    }
                )

    def _check_rule_commands(self, table: dict) -> None:
        """Check for correct rule commands (booktabs vs hline)."""
        content = table["content"]

        # Find tabular body
        tabular_match = re.search(
            r"\\begin\{tabular\*?\}(?:\{[^}]*\})?\{[^}]+\}(.*?)\\end\{tabular\*?\}",
            content,
            re.DOTALL,
        )
        if not tabular_match:
            return

        tabular_body = tabular_match.group(1)

        # Count booktabs rules
        toprule_count = len(re.findall(r"\\toprule", tabular_body))
        midrule_count = len(re.findall(r"\\midrule", tabular_body))
        bottomrule_count = len(re.findall(r"\\bottomrule", tabular_body))

        # Check for forbidden rules
        for i, line in enumerate(self.lines[table["start"] - 1 : table["end"]], table["start"]):
            stripped = line.split("%")[0]
            if r"\hline" in stripped:
                self.issues.append(
                    {
                        "line": i,
                        "level": self.LEVEL_WARNING,
                        "priority": "P1",
                        "message": "\\hline detected. Use \\toprule, \\midrule, \\bottomrule (booktabs) instead.",
                        "category": "hline",
                    }
                )
            if re.search(r"\\cline\{[^}]+\}", stripped):
                self.issues.append(
                    {
                        "line": i,
                        "level": self.LEVEL_INFO,
                        "priority": "P3",
                        "message": "\\cline detected. Consider \\cmidrule (booktabs) for partial rules under sub-headers.",
                        "category": "hline",
                    }
                )

        # Validate three-line structure
        if toprule_count == 0 and midrule_count == 0 and bottomrule_count == 0:
            # No booktabs at all — check if using hline
            hline_count = len(re.findall(r"\\hline", tabular_body))
            if hline_count > 0:
                self.issues.append(
                    {
                        "line": table["start"],
                        "level": self.LEVEL_WARNING,
                        "priority": "P1",
                        "message": f"Table uses \\hline ({hline_count}x) instead of booktabs commands. Replace with \\toprule/\\midrule/\\bottomrule.",
                        "category": "booktabs_missing",
                    }
                )
        else:
            if toprule_count != 1:
                self.issues.append(
                    {
                        "line": table["start"],
                        "level": self.LEVEL_WARNING,
                        "priority": "P2",
                        "message": f"Expected exactly 1 \\toprule, found {toprule_count}.",
                        "category": "rule_count",
                    }
                )
            if bottomrule_count != 1:
                self.issues.append(
                    {
                        "line": table["start"],
                        "level": self.LEVEL_WARNING,
                        "priority": "P2",
                        "message": f"Expected exactly 1 \\bottomrule, found {bottomrule_count}.",
                        "category": "rule_count",
                    }
                )

    def _check_caption_position(self, table: dict) -> None:
        """Check that caption appears before tabular environment."""
        content = table["content"]

        caption_pos = -1
        tabular_pos = -1

        caption_match = re.search(r"\\caption", content)
        tabular_match = re.search(r"\\begin\{tabular\*?\}", content)

        if caption_match:
            caption_pos = caption_match.start()
        if tabular_match:
            tabular_pos = tabular_match.start()

        if caption_pos < 0:
            self.issues.append(
                {
                    "line": table["start"],
                    "level": self.LEVEL_WARNING,
                    "priority": "P2",
                    "message": "No \\caption found in table environment.",
                    "category": "caption",
                }
            )
        elif tabular_pos >= 0 and caption_pos > tabular_pos:
            self.issues.append(
                {
                    "line": table["start"],
                    "level": self.LEVEL_WARNING,
                    "priority": "P2",
                    "message": "Caption should appear above the table (before \\begin{tabular}), not below.",
                    "category": "caption_position",
                }
            )

    def _check_table_notes(self, table: dict) -> None:
        """Check table note format if present."""
        content = table["content"]

        # Look for common note patterns
        has_note = False
        if re.search(r"\\item\s+Note\.", content):
            has_note = True
        if re.search(r"\\item\s+注[：:]", content):
            has_note = True
        if re.search(r"\\footnotesize\s*Note\.", content):
            has_note = True
        if re.search(r"\\footnotesize\s*注[：:]", content):
            has_note = True

        # Check if there are significance markers but no note explaining them
        if (
            re.search(r"\*\*?\*?", content)
            and not has_note
            and re.search(r"\d+\.?\d*\s*\*{1,3}", content)
        ):
            self.issues.append(
                {
                    "line": table["start"],
                    "level": self.LEVEL_INFO,
                    "priority": "P3",
                    "message": "Statistical significance markers (*/**/ ***) detected but no table note defining them. Add a note: 'Note. * p<0.05; ** p<0.01; *** p<0.001.'",
                    "category": "table_note",
                }
            )

    def _check_number_precision(self, table: dict) -> None:
        """Check for inconsistent decimal precision within columns."""
        content = table["content"]

        # Extract data rows (lines between \midrule and \bottomrule)
        data_match = re.search(r"\\midrule(.*?)\\bottomrule", content, re.DOTALL)
        if not data_match:
            return

        data_section = data_match.group(1)
        rows = [r.strip() for r in data_section.split(r"\\") if r.strip()]

        if len(rows) < 2:
            return

        # Parse columns
        parsed_rows = []
        for row in rows:
            # Remove LaTeX commands for analysis
            cleaned = re.sub(r"\\textbf\{([^}]*)\}", r"\1", row)
            cleaned = re.sub(r"\\bfseries\s*", "", cleaned)
            cleaned = re.sub(r"\$[^$]*\$", "", cleaned)
            cells = [c.strip() for c in cleaned.split("&")]
            parsed_rows.append(cells)

        if not parsed_rows:
            return

        # Check each column for precision consistency
        n_cols = max(len(r) for r in parsed_rows)
        for col_idx in range(n_cols):
            decimals_seen: set[int] = set()
            for row in parsed_rows:
                if col_idx < len(row):
                    cell = row[col_idx].strip().rstrip("*")
                    # Extract numbers
                    nums = re.findall(r"\d+\.(\d+)", cell)
                    for n in nums:
                        decimals_seen.add(len(n))

            if len(decimals_seen) > 1:
                self.issues.append(
                    {
                        "line": table["start"],
                        "level": self.LEVEL_WARNING,
                        "priority": "P3",
                        "message": f"Inconsistent decimal precision in column {col_idx + 1}: found {sorted(decimals_seen)} decimal places. Use consistent precision within each column.",
                        "category": "precision",
                    }
                )

    def _suggest_fix(self, issue: dict) -> str:
        """Generate fix suggestion for an issue."""
        cat = issue.get("category", "")
        if cat == "vertical_lines":
            return "Remove all | characters from the column specification."
        if cat == "hline":
            return "Replace \\hline with \\toprule (first), \\midrule (after header), \\bottomrule (last)."
        if cat == "booktabs_missing":
            return "Add \\usepackage{booktabs} and replace \\hline with \\toprule/\\midrule/\\bottomrule."
        if cat == "caption_position":
            return "Move \\caption{...} before \\begin{tabular}."
        if cat == "precision":
            return "Align all values in the column to the same number of decimal places."
        if cat == "package":
            return "Add \\usepackage{booktabs} to the preamble."
        return ""

    def generate_report(self, result: dict) -> str:
        """Generate human-readable report."""
        lines = []
        lines.append("=" * 60)
        lines.append("Table Structure Check Report")
        lines.append("=" * 60)
        lines.append(f"File: {result['file']}")
        lines.append(f"Tables found: {result['table_count']}")
        lines.append(f"Status: {result['status']}")
        lines.append(f"Issues: {result['issue_count']}")

        if result["issues"]:
            lines.append("")
            lines.append("-" * 60)

            by_category: dict[str, list[dict]] = {}
            for issue in result["issues"]:
                cat = issue.get("category", "other")
                if cat not in by_category:
                    by_category[cat] = []
                by_category[cat].append(issue)

            for category, issues in sorted(by_category.items()):
                lines.append(f"\n[{category.upper()}] ({len(issues)} issues)")
                for issue in issues:
                    prefix = f"  Line {issue['line']}" if issue["line"] else "  Global"
                    lines.append(f"{prefix}: [{issue['level']}] {issue['message']}")
                    if issue.get("fix"):
                        lines.append(f"    Fix: {issue['fix']}")

        lines.append("")
        lines.append("=" * 60)
        return "\n".join(lines)


def main():
    parser = argparse.ArgumentParser(
        description="Table Structure Checker - three-line table compliance"
    )
    parser.add_argument("tex_file", help=".tex file to check")
    parser.add_argument(
        "--fix-suggestions", "-f", action="store_true", help="Include fix suggestions"
    )
    parser.add_argument("--json", "-j", action="store_true", help="Output in JSON format")

    args = parser.parse_args()

    if not Path(args.tex_file).exists():
        print(f"[ERROR] File not found: {args.tex_file}")
        sys.exit(1)

    checker = TableChecker(args.tex_file)
    result = checker.check(fix_suggestions=args.fix_suggestions)

    if args.json:
        print(json.dumps(result, indent=2))
    else:
        print(checker.generate_report(result))

    sys.exit(1 if result["status"] == "FAIL" else 0)


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""
Academic expression improver (MVP) for LaTeX/Typst papers.
"""

import argparse
import re
import sys
from pathlib import Path

try:
    from parsers import get_parser
except ImportError:
    sys.path.append(str(Path(__file__).parent))
    from parsers import get_parser


WEAK_VERBS = {
    r"\buse\b": "employ",
    r"\bget\b": "obtain",
    r"\bmake\b": "develop",
    r"\bshow\b": "demonstrate",
}

WEAK_PHRASES = {
    r"\bvery\b": "highly",
    r"\ba lot of\b": "many",
    r"\bkind of\b": "",
}


def _enhance(text: str) -> tuple[str, list[str]]:
    revised = text
    changes: list[str] = []
    for pattern, replacement in WEAK_VERBS.items():
        if re.search(pattern, revised, re.IGNORECASE):
            revised = re.sub(pattern, replacement, revised, flags=re.IGNORECASE)
            changes.append(f"Weak verb replaced: {pattern} -> {replacement}")
    for pattern, replacement in WEAK_PHRASES.items():
        if re.search(pattern, revised, re.IGNORECASE):
            revised = re.sub(pattern, replacement, revised, flags=re.IGNORECASE)
            changes.append(f"Weak phrase adjusted: {pattern} -> {replacement or '[deleted]'}")
    revised = re.sub(r"\s+", " ", revised).strip()
    return revised, changes


def analyze(file_path: Path, section: str | None) -> list[str]:
    parser = get_parser(file_path)
    content = file_path.read_text(encoding="utf-8", errors="ignore")
    lines = content.split("\n")
    sections = parser.split_sections(content)

    if section:
        key = section.lower()
        if key not in sections:
            return [f"% ERROR [Severity: Critical] [Priority: P0]: Section not found: {section}"]
        ranges = [sections[key]]
    else:
        ranges = list(sections.values()) if sections else [(1, len(lines))]

    out: list[str] = []
    for start, end in ranges:
        for line_no in range(start, min(end, len(lines)) + 1):
            raw = lines[line_no - 1].strip()
            if not raw or raw.startswith(parser.get_comment_prefix()):
                continue
            visible = parser.extract_visible_text(raw)
            if not visible:
                continue
            revised, changes = _enhance(visible)
            if revised.lower() == visible.lower() or not changes:
                continue
            out.extend(
                [
                    f"% EXPRESSION (Line {line_no}) [Severity: Minor] [Priority: P2]: Improve academic tone",
                    f"% Original: {visible}",
                    f"% Revised:  {revised}",
                    f"% Rationale: {'; '.join(changes)}",
                    "",
                ]
            )
    if not out:
        out.append("% EXPRESSION: No weak-expression patterns detected.")
    return out


def main() -> int:
    cli = argparse.ArgumentParser(
        description="Academic expression improvement for LaTeX/Typst files"
    )
    cli.add_argument("file", type=Path, help="Target .tex/.typ file")
    cli.add_argument("--section", help="Section name to analyze")
    args = cli.parse_args()

    if not args.file.exists():
        print(f"[ERROR] File not found: {args.file}", file=sys.stderr)
        return 1

    print("\n".join(analyze(args.file, args.section)))
    return 0


if __name__ == "__main__":
    sys.exit(main())

"""
Document Parsers for Academic Writing Skills
Support for LaTeX and Typst document parsing.
"""

import re
from abc import ABC, abstractmethod
from typing import Any


class DocumentParser(ABC):
    """Abstract base class for document parsers."""

    @abstractmethod
    def split_sections(self, content: str) -> dict[str, tuple[int, int]]:
        """
        Split document into sections.
        Returns map of {section_name: (start_line, end_line)}.
        """
        pass

    @abstractmethod
    def extract_visible_text(self, line: str) -> str:
        """
        Extract text visible to reader, preserving structure markers.
        Used for line-by-line AI trace checking.
        """
        pass

    @abstractmethod
    def clean_text(self, content: str, keep_structure: bool = False) -> str:
        """
        Extract pure prose text, removing all markup.
        Used for prose extraction and word counting.
        """
        pass

    @abstractmethod
    def get_comment_prefix(self) -> str:
        """Get the comment prefix for the language."""
        pass


class LatexParser(DocumentParser):
    """Parser for LaTeX documents."""

    # Section patterns
    SECTION_PATTERNS = {
        "abstract": r"\\begin{abstract}|\\section*?{abstract}?",
        "introduction": r"\\section*?{Introduction}|\\section*?{INTRODUCTION}",
        "related": r"\\section*?{Related\s+Work}|\\section*?{RELATED\s+WORK}",
        "method": r"\\section*?{.*(?:Method|Methodology|Approach)}",
        "experiment": r"\\section*?{.*(?:Experiment|Evaluation|Implementation)}",
        "result": r"\\section*?{.*(?:Result|Performance)}",
        "discussion": r"\\section*?{.*(?:Discussion|Analysis)}",
        "conclusion": r"\\section*?{.*(?:Conclusion|Conclusions)}",
    }

    # Preservation patterns for visible text extraction
    PRESERVE_PATTERNS = [
        r"\\cite{[^}]+}",  # Citations
        r"\\ref{[^}]+}",  # References
        r"\\label{[^}]+}",  # Labels
        r"\\eqref{[^}]+}",  # Equation references
        r"\\autoref{[^}]+}",  # Auto references
        r"\$\$[^$]*\$\$",  # Display math
        r"\$[^$]*\$",  # Inline math
        r"\\begin{equation}.*?\\end{equation}",  # Equations
        r"\\begin{align}.*?\\end{align}",  # Align environments
        r"\\begin{.*?}.*?\\end{.*?}",  # Generic environments
        r"\\includegraphics(?:\[[^]]*\])?\{[^}]+\}",  # Images
        r"\\caption{[^}]+}",  # Captions
    ]

    # Environments to skip entirely for clean text
    SKIP_ENVIRONMENTS = [
        "equation",
        "equation*",
        "align",
        "align*",
        "gather",
        "gather*",
        "multline",
        "multline*",
        "eqnarray",
        "eqnarray*",
        "displaymath",
        "figure",
        "figure*",
        "table",
        "table*",
        "tabular",
        "tabular*",
        "lstlisting",
        "verbatim",
        "minted",
        "algorithm",
        "algorithmic",
    ]

    def get_comment_prefix(self) -> str:
        return "%"

    def split_sections(self, content: str) -> dict[str, tuple[int, int]]:
        lines = content.split("\n")
        sections = {}
        current_section = "preamble"
        start_line = 0

        for i, line in enumerate(lines, 1):
            for section_name, pattern in self.SECTION_PATTERNS.items():
                if re.search(pattern, line, re.IGNORECASE):
                    if current_section != "preamble":
                        sections[current_section] = (start_line, i - 1)
                    current_section = section_name
                    start_line = i
                    break

        # Last section
        if current_section != "preamble":
            sections[current_section] = (start_line, len(lines))

        return sections

    def extract_visible_text(self, line: str) -> str:
        # Preserve structure markers logic
        preserved = []
        temp_line = line

        for pattern in self.PRESERVE_PATTERNS:
            matches = list(re.finditer(pattern, temp_line, re.DOTALL))
            for match in reversed(matches):
                preserved.append(
                    {"start": match.start(), "end": match.end(), "text": match.group()}
                )
                # Replace with placeholder of same length to keep indices valid
                placeholder = " " * (match.end() - match.start())
                temp_line = temp_line[: match.start()] + placeholder + temp_line[match.end() :]

        preserved.sort(key=lambda x: x["start"])

        visible_parts = []
        last_end = 0

        for item in preserved:
            if item["start"] > last_end:
                visible_parts.append(temp_line[last_end : item["start"]])
            last_end = item["end"]

        if last_end < len(temp_line):
            visible_parts.append(temp_line[last_end:])

        return " ".join(visible_parts).strip()

    def clean_text(self, content: str, keep_structure: bool = False) -> str:
        # Remove comments
        content = re.sub(r"(?<!\\)%.*", "", content)

        # Remove skip environments
        for env in self.SKIP_ENVIRONMENTS:
            pattern = rf"\\begin{{{env}}}.*?\\end{{{env}}}"
            content = re.sub(pattern, "", content, flags=re.DOTALL)

        # Remove inline math
        content = re.sub(r"\$[^$]+\$", "", content)
        content = re.sub(r"\\[^]]*\\]", "", content, flags=re.DOTALL)
        content = re.sub(r"\\\(.*?\\\)", "", content, flags=re.DOTALL)

        # Formatting
        if keep_structure:
            content = re.sub(r"\\section\*?{([^}]+)}", r"\n\n## \1\n\n", content)
            content = re.sub(r"\\subsection\*?{([^}]+)}", r"\n\n### \1\n\n", content)
        else:
            content = re.sub(r"\\(?:sub)*section\*?{[^}]+}", "", content)

        # Remove commands
        content = re.sub(r"\\[a-zA-Z]+\*?(?:\[[^\]]*\])?{([^}]*)}", r"\1", content)
        content = re.sub(r"\\[a-zA-Z]+\*?", "", content)
        content = re.sub(r"[{}]", "", content)

        # Cleanup whitespace
        content = re.sub(r"\n+", "\n", content)
        content = re.sub(r" +", " ", content)
        content = re.sub(r"\.(\s*\.)+", ".", content)  # Fix multiple periods

        return content.strip()


class TypstParser(DocumentParser):
    """Parser for Typst documents."""

    # Section patterns (Heading 1-3)
    # Matches: = Introduction or == Related Work
    SECTION_PATTERNS = {
        "introduction": r"^=\s+(?:Introduction|INTRODUCTION|绪论|引言)",
        "related": r"^=\s+(?:Related\s+Work|RELATED\s+WORK|相关工作|文献综述)",
        "method": r"^=\s+.*(?:Method|Methodology|Approach|方法|原理|设计)",
        "experiment": r"^=\s+.*(?:Experiment|Evaluation|Implementation|实验|实现|测试)",
        "result": r"^=\s+.*(?:Result|Performance|结果|性能)",
        "discussion": r"^=\s+.*(?:Discussion|Analysis|讨论|分析)",
        "conclusion": r"^=\s+.*(?:Conclusion|Conclusions|结论|总结与展望)",
        "abstract": r"#abstract\[",
    }

    PRESERVE_PATTERNS = [
        r"@[a-zA-Z0-9_-]+",  # Citations @key
        r"#cite\([^)]+\)",  # Function calls #cite()
        r"#figure\([^)]+\)",  # Figures
        r"#table\([^)]+\)",  # Tables
        r"\$[^$]+\$",  # Math $...$
        r"//.*",  # Line comments
        r"/\*.*?\*/",  # Block comments
        r"<[a-zA-Z0-9_-]+>",  # Labels <label>
        r"#link\([^)]+\)",  # Links
    ]

    def get_comment_prefix(self) -> str:
        return "//"

    def split_sections(self, content: str) -> dict[str, tuple[int, int]]:
        lines = content.split("\n")
        sections = {}
        current_section = "preamble"
        start_line = 0

        for i, line in enumerate(lines, 1):
            line = line.strip()
            # Ignore comments
            if line.startswith("//"):
                continue

            for section_name, pattern in self.SECTION_PATTERNS.items():
                if re.search(pattern, line, re.IGNORECASE):
                    if current_section != "preamble":
                        sections[current_section] = (start_line, i - 1)
                    current_section = section_name
                    start_line = i
                    break

        if current_section != "preamble":
            sections[current_section] = (start_line, len(lines))

        return sections

    def extract_visible_text(self, line: str) -> str:
        # Same logic as LatexParser but with Typst patterns
        temp_line = line

        # Remove comments first for Typst
        if "//" in temp_line:
            temp_line = temp_line.split("//")[0]

        preserved = []
        for pattern in self.PRESERVE_PATTERNS:
            matches = list(re.finditer(pattern, temp_line, re.DOTALL))
            for match in reversed(matches):
                preserved.append(
                    {"start": match.start(), "end": match.end(), "text": match.group()}
                )
                placeholder = " " * (match.end() - match.start())
                temp_line = temp_line[: match.start()] + placeholder + temp_line[match.end() :]

        preserved.sort(key=lambda x: x["start"])

        # Extract visible logic... (duplicated, could refactor to base)
        # But keeping separate for now to be safe
        visible_parts = []
        last_end = 0
        for item in preserved:
            if item["start"] > last_end:
                visible_parts.append(temp_line[last_end : item["start"]])
            last_end = item["end"]
        if last_end < len(temp_line):
            visible_parts.append(temp_line[last_end:])

        return " ".join(visible_parts).strip()

    def clean_text(self, content: str, keep_structure: bool = False) -> str:
        # Remove comments
        content = re.sub(r"//.*", "", content)
        content = re.sub(r"/\*.*?\*/", "", content, flags=re.DOTALL)

        # Remove math
        content = re.sub(r"\$[^$]+\$", "", content)

        # Handle headers
        if keep_structure:
            content = re.sub(r"^=+\s+(.+)$", r"\n\n## \1\n\n", content, flags=re.MULTILINE)
        else:
            content = re.sub(r"^=+\s+.+$", "", content, flags=re.MULTILINE)

        # Remove function calls #func(...) - basic support
        # This is hard with regex due to nested parenthesis, simplified here
        content = re.sub(r"#[a-zA-Z0-9_]+\([^)]*\)", "", content)
        content = re.sub(r"@[a-zA-Z0-9_-]+", "", content)
        content = re.sub(r"<[a-zA-Z0-9_-]+>", "", content)

        # Cleanup
        content = re.sub(r"\n+", "\n", content)
        content = re.sub(r" +", " ", content)
        content = re.sub(r"\.(\s*\.)+", ".", content)  # Fix multiple periods
        return content.strip()


def get_parser(file_path: Any) -> DocumentParser:
    """Factory method to get appropriate parser."""
    path_str = str(file_path).lower()
    if path_str.endswith(".typ"):
        return TypstParser()
    return LatexParser()


def _normalize_whitespace(text: str) -> str:
    return re.sub(r"\s+", " ", text).strip()


def _extract_balanced_block(content: str, start_idx: int, opener: str, closer: str) -> str:
    """Extract a balanced block body from content starting at opener index."""
    if start_idx < 0 or start_idx >= len(content) or content[start_idx] != opener:
        return ""

    depth = 0
    block_start = -1

    for i in range(start_idx, len(content)):
        char = content[i]
        if char == opener:
            depth += 1
            if depth == 1:
                block_start = i + 1
        elif char == closer:
            depth -= 1
            if depth == 0 and block_start >= 0:
                return content[block_start:i]
            if depth < 0:
                return ""
    return ""


def _strip_typst_markup(text: str) -> str:
    """Strip lightweight Typst markup for title/abstract extraction."""
    cleaned = text
    cleaned = re.sub(r"#\w+\([^)]*\)", " ", cleaned)

    # Collapse simple bracket macros repeatedly (e.g., #emph[Paper], nested forms).
    while True:
        collapsed = re.sub(r"#\w+\[([^\[\]]*)\]", r"\1", cleaned)
        if collapsed == cleaned:
            break
        cleaned = collapsed

    cleaned = re.sub(r"[\[\]]", " ", cleaned)
    return _normalize_whitespace(cleaned)


def _strip_latex_markup(text: str) -> str:
    """Strip lightweight LaTeX markup for title/abstract extraction."""
    cleaned = text
    cleaned = re.sub(r"(?<!\\)%.*", "", cleaned)
    cleaned = re.sub(r"\$[^$]*\$", " ", cleaned)
    cleaned = re.sub(r"\\[a-zA-Z]+\*?(?:\[[^\]]*\])?{([^{}]*)}", r"\1", cleaned)
    cleaned = re.sub(r"\\[a-zA-Z]+\*?", " ", cleaned)
    cleaned = re.sub(r"[{}]", " ", cleaned)
    return _normalize_whitespace(cleaned)


def extract_title(content: str) -> str:
    """Extract document title from LaTeX/Typst source content."""
    # LaTeX: \title{...}
    latex_match = re.search(r"\\title(?:\[[^\]]*\])?\{(.+?)\}", content, re.DOTALL)
    if latex_match:
        return _strip_latex_markup(latex_match.group(1))

    # Typst common: #set document(title: "...")
    typst_str = re.search(
        r"#set\s+document\s*\(\s*title\s*:\s*\"([^\"]+)\"",
        content,
        re.DOTALL,
    )
    if typst_str:
        return _normalize_whitespace(typst_str.group(1))

    # Typst bracket style: #set document(title: [ ... ])
    typst_block = re.search(r"#set\s+document\s*\(\s*title\s*:\s*\[", content, re.DOTALL)
    if typst_block:
        bracket_idx = typst_block.end() - 1
        text = _extract_balanced_block(content, bracket_idx, "[", "]")
        if text:
            return _strip_typst_markup(text)

    return ""


def extract_abstract(content: str) -> str:
    """Extract abstract text from LaTeX/Typst source content."""
    # LaTeX abstract environment
    latex_abs = re.search(r"\\begin{abstract}(.*?)\\end{abstract}", content, re.DOTALL)
    if latex_abs:
        return _strip_latex_markup(latex_abs.group(1))

    # LaTeX section-based abstract
    sec_abs = re.search(
        r"\\section\*?\{Abstract\}(.*?)(?=\\section\*?\{|\\end\{document\}|\Z)",
        content,
        re.DOTALL | re.IGNORECASE,
    )
    if sec_abs:
        return _strip_latex_markup(sec_abs.group(1))

    # Typst: #abstract[...]
    typst_abs = re.search(r"#abstract\[", content, re.DOTALL)
    if typst_abs:
        bracket_idx = typst_abs.end() - 1
        text = _extract_balanced_block(content, bracket_idx, "[", "]")
        if text:
            return _strip_typst_markup(text)

    typst_heading_abs = re.search(
        r"^=\s+摘要\s*\n(.*?)(?=^=\s+|\Z)",
        content,
        re.DOTALL | re.MULTILINE,
    )
    if typst_heading_abs:
        return _strip_typst_markup(typst_heading_abs.group(1))

    return ""


def extract_latex_citation_keys(content: str) -> set[str]:
    """
    Extract citation keys from LaTeX source.
    Supports \\cite, \\citep, \\citet, \\nocite and variants with optional arguments.
    """
    keys: set[str] = set()
    pattern = re.compile(r"\\(?:cite\w*|nocite)\*?(?:\[[^\]]*\]\s*)*\{([^}]*)\}")
    for match in pattern.finditer(content):
        raw = match.group(1)
        for key in raw.split(","):
            normalized = key.strip()
            if normalized:
                keys.add(normalized)
    return keys

#!/usr/bin/env python3
"""
Chinese -> English academic translation helper (MVP).

This script is terminology-driven and provides:
1) terminology confirmation table
2) draft translation
3) ambiguity notes requiring manual confirmation

It preserves LaTeX commands and math segments verbatim while translating
the surrounding visible prose.
"""

import argparse
import re
import sys
from pathlib import Path

TERMINOLOGY = {
    "deep-learning": {
        "注意力机制": "attention mechanism",
        "损失函数": "loss function",
        "神经网络": "neural network",
        "时间序列预测": "time series forecasting",
        "模型": "model",
    },
    "time-series": {
        "时间序列": "time series",
        "预测": "forecasting",
        "滑动窗口": "sliding window",
        "趋势": "trend",
        "季节性": "seasonality",
    },
    "industrial-control": {
        "故障检测": "fault detection",
        "工业控制": "industrial control",
        "控制系统": "control system",
        "实时": "real-time",
        "鲁棒性": "robustness",
    },
}

AMBIGUOUS_TERMS = {
    "控制": ["control", "controller", "regulation"],
    "性能": ["performance", "efficiency"],
    "优化": ["optimization", "improvement"],
}

COMMON_PATTERNS = {
    "本文提出": "We propose",
    "实验结果表明": "Experimental results demonstrate that",
    "与...相比": "Compared with ...",
    "在...中": "in ...",
}
PROTECTED_RE = re.compile(
    r"(\\[a-zA-Z]+\*?(?:\[[^\]]*\])?(?:\{[^{}]*\})?|"
    r"\$[^$]*\$|"
    r"\\begin\{[^}]+\}.*?\\end\{[^}]+\})",
    re.DOTALL,
)


def _load_source(input_arg: str) -> str:
    path = Path(input_arg)
    if path.exists() and path.is_file():
        return path.read_text(encoding="utf-8", errors="ignore")
    return input_arg


def _build_term_table(text: str, domain: str) -> list[tuple[str, str, str]]:
    table: list[tuple[str, str, str]] = []
    domain_terms = TERMINOLOGY.get(domain, {})
    for zh, en in domain_terms.items():
        if zh in text:
            table.append((zh, en, domain))
    return table


def _mask_protected(text: str) -> tuple[str, dict[str, str]]:
    masked = text
    replacements: dict[str, str] = {}

    for idx, match in enumerate(PROTECTED_RE.finditer(text)):
        placeholder = f"@@LATEX_{idx}@@"
        replacements[placeholder] = match.group(0)
        masked = masked.replace(match.group(0), placeholder, 1)

    return masked, replacements


def _restore_protected(text: str, replacements: dict[str, str]) -> str:
    restored = text
    for placeholder, original in replacements.items():
        restored = restored.replace(placeholder, original)
    return restored


def _draft_translate(text: str, domain: str) -> tuple[str, list[str]]:
    translated, replacements = _mask_protected(text)
    notes: list[str] = []

    for zh, en in TERMINOLOGY.get(domain, {}).items():
        if zh in translated:
            translated = translated.replace(zh, en)

    for zh, en in COMMON_PATTERNS.items():
        if zh in translated:
            translated = translated.replace(zh, en)

    for term, options in AMBIGUOUS_TERMS.items():
        if term in translated:
            notes.append(f"Ambiguous term '{term}' -> choose one: {', '.join(options)}")

    # Minimal sentence formatting
    translated = translated.replace("。", ". ").replace("，", ", ")
    translated = " ".join(translated.split())
    translated = _restore_protected(translated, replacements)
    return translated, notes


def translate(input_arg: str, domain: str) -> str:
    text = _load_source(input_arg)
    table = _build_term_table(text, domain)
    draft, notes = _draft_translate(text, domain)

    lines: list[str] = []
    lines.append("### Terminology Confirmation")
    lines.append("| 中文 | English | Domain |")
    lines.append("|------|---------|--------|")
    if table:
        for zh, en, dom in table:
            lines.append(f"| {zh} | {en} | {dom} |")
    else:
        lines.append("| (none detected) | - | - |")

    lines.append("\n### Translation Draft")
    lines.append(f"% ORIGINAL: {text}")
    lines.append(f"% TRANSLATION: {draft}")

    lines.append("\n### Notes")
    if notes:
        for note in notes:
            lines.append(f"- ⚠️ [PENDING CONFIRMATION] {note}")
    else:
        lines.append("- No high-risk ambiguous terms detected by rule set.")

    return "\n".join(lines)


def main() -> int:
    cli = argparse.ArgumentParser(description="Terminology-driven academic translation helper")
    cli.add_argument("input", help="Chinese text or a file path containing Chinese text")
    cli.add_argument(
        "--domain",
        choices=["deep-learning", "time-series", "industrial-control"],
        default="deep-learning",
        help="Domain terminology set",
    )
    cli.add_argument("--output", help="Output file path")
    args = cli.parse_args()

    result = translate(args.input, args.domain)
    if args.output:
        Path(args.output).write_text(result, encoding="utf-8")
        print(f"[SUCCESS] Translation report written to: {args.output}")
    else:
        print(result)
    return 0


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
"""
BibTeX Verification Script - Check bibliography integrity and citation consistency.

Usage:
    uv run python -B verify_bib.py references.bib
    uv run python -B verify_bib.py references.bib --tex main.tex
    uv run python -B verify_bib.py references.bib --standard gb7714
    uv run python -B verify_bib.py references.bib --online-check --output verification_needed.json
"""

import argparse
import json
import re
import sys
from pathlib import Path

try:
    from parsers import extract_latex_citation_keys
except ImportError:
    sys.path.append(str(Path(__file__).parent))
    from parsers import extract_latex_citation_keys


class BibTeXVerifier:
    """Verify BibTeX file integrity and citation consistency."""

    REQUIRED_FIELDS = {
        "article": ["author", "title", "journal", "year"],
        "inproceedings": ["author", "title", "booktitle", "year"],
        "book": ["author", "title", "publisher", "year"],
    }

    GB7714_RECOMMENDED = ["doi", "url", "urldate"]

    # Style-specific author thresholds for et al.
    STYLE_ET_AL_THRESHOLD = {
        "ieee": 6,
        "apa": 20,  # APA lists up to 20; in-text uses et al. for 3+
        "vancouver": 6,
        "nature": 5,
    }

    # Style-specific required fields beyond the base set
    STYLE_EXTRA_FIELDS = {
        "ieee": {"article": ["volume", "pages"]},
        "apa": {"article": ["volume"]},
        "vancouver": {"article": ["volume", "pages"]},
        "nature": {"article": ["volume", "pages"]},
    }

    def __init__(
        self,
        bib_file: str,
        standard: str = "default",
        tex_file: str | None = None,
        online: bool = False,
        email: str | None = None,
        online_timeout: float = 10.0,
        style: str = "ieee",
    ):
        self.bib_file = Path(bib_file).resolve()
        self.standard = standard
        self.tex_file = Path(tex_file).resolve() if tex_file else None
        self.entries: list[dict] = []
        self.parse_issues: list[dict] = []
        self.online = online
        self.email = email
        self.online_timeout = online_timeout
        self.style = style.lower()

    def parse(self) -> list[dict]:
        """Parse BibTeX file into entries."""
        try:
            content = self.bib_file.read_text(encoding="utf-8", errors="ignore")
        except Exception as exc:
            self.parse_issues.append(
                {
                    "severity": "error",
                    "type": "file_error",
                    "message": f"Failed to read BibTeX file: {exc}",
                }
            )
            return []

        entries = []
        seen_keys: dict[str, str] = {}

        # Entry-level extraction (best-effort for common BibTeX files)
        entry_pattern = r"@(\w+)\s*{\s*([^,]+)\s*,([^@]*?)(?=\n\s*@|\Z)"
        for match in re.finditer(entry_pattern, content, re.DOTALL):
            entry_type = match.group(1).lower().strip()
            key = match.group(2).strip()
            fields = self._parse_fields(match.group(3))
            entries.append(
                {"type": entry_type, "key": key, "fields": fields, "raw": match.group(0)}
            )

            key_lower = key.lower()
            if key_lower in seen_keys:
                self.parse_issues.append(
                    {
                        "severity": "error",
                        "type": "duplicate_key",
                        "key": key,
                        "message": f"Duplicate key detected: '{seen_keys[key_lower]}' and '{key}'",
                    }
                )
            else:
                seen_keys[key_lower] = key

        self.entries = entries
        return entries

    def _parse_fields(self, fields_str: str) -> dict[str, str]:
        fields: dict[str, str] = {}
        # Parse field = {value} or "value" or number
        field_pattern = r'(\w+)\s*=\s*(?:\{([^{}]*(?:\{[^{}]*\}[^{}]*)*)\}|"([^"]*)"|(\d+))'
        for match in re.finditer(field_pattern, fields_str):
            name = match.group(1).lower()
            val = match.group(2) or match.group(3) or match.group(4) or ""
            fields[name] = val.strip()
        return fields

    def verify(self) -> dict:
        """Run full verification and return structured results."""
        if not self.entries:
            self.parse()

        results: dict[str, object] = {
            "total_entries": len(self.entries),
            "valid_entries": 0,
            "issues": list(self.parse_issues),
            "status": "PASS",
            "needs_online_check": [],
            "missing_in_bib": [],
            "unused_in_tex": [],
        }

        for entry in self.entries:
            entry_issues = self._verify_entry(entry)
            if entry_issues:
                results["issues"].extend(entry_issues)
            else:
                results["valid_entries"] += 1

            # Style-specific checks
            style_issues = self._check_style_compliance(entry)
            results["issues"].extend(style_issues)

            # Check for missing identifiers (DOI/URL)
            if "doi" not in entry["fields"] and "url" not in entry["fields"]:
                results["needs_online_check"].append(
                    {
                        "key": entry["key"],
                        "title": entry["fields"].get("title", "Unknown Title"),
                        "author": entry["fields"].get("author", "Unknown Author"),
                    }
                )

            if self.standard == "gb7714":
                self._check_gb7714_recommended(entry, results["issues"])

        if self.tex_file:
            missing_in_bib, unused_in_tex, tex_issues = self._check_citation_consistency()
            results["missing_in_bib"] = sorted(missing_in_bib)
            results["unused_in_tex"] = sorted(unused_in_tex)
            results["issues"].extend(tex_issues)

        # Online verification (when --online and online_bib_verify is available)
        if self.online:
            try:
                from online_bib_verify import OnlineBibVerifier

                online_verifier = OnlineBibVerifier(
                    polite_email=self.email,
                    timeout=self.online_timeout,
                )
                for entry_info in results["needs_online_check"]:
                    entry_dict = {
                        "key": entry_info["key"],
                        "title": entry_info.get("title", ""),
                        "author": entry_info.get("author", ""),
                    }
                    # Find full entry fields
                    for entry in self.entries:
                        if entry["key"] == entry_info["key"]:
                            entry_dict.update(entry["fields"])
                            break
                    result = online_verifier.verify_entry(entry_dict)
                    if result.status == "mismatch":
                        for m in result.mismatches:
                            results["issues"].append(
                                {
                                    "key": result.bib_key,
                                    "type": "metadata_mismatch",
                                    "severity": "error",
                                    "message": f"Online verification mismatch: {m}",
                                }
                            )
                    elif result.status == "not_found":
                        results["issues"].append(
                            {
                                "key": result.bib_key,
                                "type": "not_found_online",
                                "severity": "warning",
                                "message": "Entry not found in online databases",
                            }
                        )
                    elif result.status == "verified" and result.suggested_doi:
                        results["issues"].append(
                            {
                                "key": result.bib_key,
                                "type": "doi_suggestion",
                                "severity": "warning",
                                "message": f"Consider adding DOI: {result.suggested_doi}",
                            }
                        )
            except ImportError:
                print("# Warning: online_bib_verify.py not found, skipping online verification")

        if results["issues"]:
            has_error = any(item["severity"] == "error" for item in results["issues"])
            results["status"] = "FAIL" if has_error else "WARNING"

        return results

    def _verify_entry(self, entry: dict) -> list[dict]:
        issues: list[dict] = []
        entry_type = entry["type"]
        entry_key = entry["key"]
        fields = entry["fields"]

        required = self.REQUIRED_FIELDS.get(entry_type, [])
        for field in required:
            if field not in fields or not fields[field]:
                if field == "author" and "editor" in fields:
                    continue
                issues.append(
                    {
                        "key": entry_key,
                        "type": "missing_field",
                        "field": field,
                        "severity": "error",
                        "message": f"Missing required field '{field}'",
                    }
                )

        # Title case check (simplified heuristic)
        title = fields.get("title", "")
        if title and re.search(r"\b[A-Z]{2,}\b", title) and "{" not in title:
            issues.append(
                {
                    "key": entry_key,
                    "type": "caps",
                    "severity": "warning",
                    "message": "Unprotected uppercase in title",
                }
            )

        return issues

    def _check_style_compliance(self, entry: dict) -> list[dict]:
        """Check entry against style-specific rules (IEEE/APA/Vancouver/Nature)."""
        issues: list[dict] = []
        fields = entry["fields"]
        entry_key = entry["key"]
        entry_type = entry["type"]

        # Check page format (en dash)
        pages = fields.get("pages", "")
        if pages and "-" in pages and "--" not in pages:
            issues.append(
                {
                    "key": entry_key,
                    "type": "page_format",
                    "severity": "warning",
                    "message": (
                        f"Page range uses hyphen '{pages}'. Use en dash (--) for page ranges."
                    ),
                }
            )

        # Check style-specific extra required fields
        extra = self.STYLE_EXTRA_FIELDS.get(self.style, {}).get(entry_type, [])
        for field in extra:
            if field not in fields or not fields[field]:
                issues.append(
                    {
                        "key": entry_key,
                        "type": "style_missing_field",
                        "severity": "warning",
                        "message": (
                            f"[{self.style.upper()}] Missing recommended field "
                            f"'{field}' for {entry_type}"
                        ),
                    }
                )

        # Check author count vs et al. threshold (informational)
        author = fields.get("author", "")
        if author:
            # Count authors by splitting on " and "
            author_count = len(re.split(r"\s+and\s+", author))
            threshold = self.STYLE_ET_AL_THRESHOLD.get(self.style, 6)
            if author_count > threshold:
                issues.append(
                    {
                        "key": entry_key,
                        "type": "author_count",
                        "severity": "info",
                        "message": (
                            f"[{self.style.upper()}] {author_count} authors listed; "
                            f"style uses et al. after {threshold}. "
                            "Ensure bibliography style handles truncation."
                        ),
                    }
                )

        # DOI requirement varies by style
        if (
            self.style in ("ieee", "nature", "apa")
            and "doi" not in fields
            and entry_type in ("article", "inproceedings")
        ):
            issues.append(
                {
                    "key": entry_key,
                    "type": "doi_missing",
                    "severity": "warning",
                    "message": (
                        f"[{self.style.upper()}] DOI recommended for {entry_type} entries."
                    ),
                }
            )

        return issues

    def _check_gb7714_recommended(self, entry: dict, issues: list[dict]) -> None:
        fields = entry["fields"]
        entry_key = entry["key"]
        for field in self.GB7714_RECOMMENDED:
            if field not in fields:
                issues.append(
                    {
                        "key": entry_key,
                        "type": "gb7714_recommended",
                        "field": field,
                        "severity": "warning",
                        "message": f"GB7714 recommends field '{field}'",
                    }
                )

    def _check_citation_consistency(self) -> tuple[set[str], set[str], list[dict]]:
        issues: list[dict] = []
        if not self.tex_file or not self.tex_file.exists():
            msg = (
                f"TeX file not found: {self.tex_file}" if self.tex_file else "TeX file not provided"
            )
            issues.append(
                {
                    "severity": "error",
                    "type": "tex_file_error",
                    "message": msg,
                }
            )
            return set(), set(), issues

        try:
            tex_content = self.tex_file.read_text(encoding="utf-8", errors="ignore")
        except Exception as exc:
            issues.append(
                {
                    "severity": "error",
                    "type": "tex_file_error",
                    "message": f"Failed to read TeX file: {exc}",
                }
            )
            return set(), set(), issues

        cited_keys = extract_latex_citation_keys(tex_content)
        bib_keys = {entry["key"] for entry in self.entries}

        missing_in_bib = cited_keys - bib_keys
        unused_in_tex = bib_keys - cited_keys

        if missing_in_bib:
            issues.append(
                {
                    "severity": "error",
                    "type": "missing_in_bib",
                    "message": f"Citations not found in BibTeX: {', '.join(sorted(missing_in_bib))}",
                }
            )
        if unused_in_tex:
            issues.append(
                {
                    "severity": "warning",
                    "type": "unused_in_tex",
                    "message": f"Unused BibTeX entries: {', '.join(sorted(unused_in_tex))}",
                }
            )

        return missing_in_bib, unused_in_tex, issues

    def generate_report(self, result: dict) -> str:
        lines = []
        lines.append(f"BibTeX Check: {self.bib_file}")
        lines.append(f"Status: {result['status']}")
        lines.append(f"Total entries: {result['total_entries']}")
        lines.append(f"Valid entries: {result['valid_entries']}")

        if self.tex_file:
            lines.append(f"TeX file: {self.tex_file}")
            lines.append(f"missing_in_bib: {len(result['missing_in_bib'])}")
            lines.append(f"unused_in_tex: {len(result['unused_in_tex'])}")

        if result["issues"]:
            lines.append("\nIssues:")
            for issue in result["issues"]:
                key_suffix = f" @{issue['key']}" if issue.get("key") else ""
                lines.append(f"  [{issue['severity'].upper()}]{key_suffix}: {issue['message']}")

        if result["needs_online_check"]:
            lines.append(
                f"\n[INFO] {len(result['needs_online_check'])} entries missing DOI/URL "
                "(Use --online-check to export list)"
            )
            lines.append(
                "[TIP] AI-generated citations have ~40% error rate. "
                "Verify entries without DOI/URL using Semantic Scholar API or CrossRef. "
                "See references/CITATION_VERIFICATION.md for verification workflow."
            )

        if result["missing_in_bib"]:
            lines.append(f"[INFO] missing_in_bib keys: {', '.join(result['missing_in_bib'])}")
        if result["unused_in_tex"]:
            lines.append(f"[INFO] unused_in_tex keys: {', '.join(result['unused_in_tex'])}")

        return "\n".join(lines)


def main() -> int:
    parser = argparse.ArgumentParser(description="BibTeX Verification")
    parser.add_argument("bib_file", help=".bib file")
    parser.add_argument("--tex", help="Main .tex file for citation consistency checks")
    parser.add_argument("--standard", choices=["default", "gb7714"], default="default")
    parser.add_argument(
        "--style",
        choices=["ieee", "apa", "vancouver", "nature"],
        default="ieee",
        help="Citation style for style-specific validation (default: ieee)",
    )
    parser.add_argument(
        "--online-check", action="store_true", help="Generate list for online verification"
    )
    parser.add_argument(
        "--online",
        action="store_true",
        help="Enable online verification via CrossRef/Semantic Scholar",
    )
    parser.add_argument("--email", help="Email for CrossRef polite pool (faster rate limits)")
    parser.add_argument(
        "--online-timeout",
        type=float,
        default=10.0,
        help="Timeout per API request in seconds",
    )
    parser.add_argument("--output", help="Output JSON file path")
    parser.add_argument("--json", action="store_true", help="Print full JSON result")

    args = parser.parse_args()

    if not Path(args.bib_file).exists():
        print(f"[ERROR] File not found: {args.bib_file}", file=sys.stderr)
        return 1

    verifier = BibTeXVerifier(
        args.bib_file,
        args.standard,
        args.tex,
        online=getattr(args, "online", False),
        email=getattr(args, "email", None),
        online_timeout=getattr(args, "online_timeout", 10.0),
        style=getattr(args, "style", "ieee"),
    )
    result = verifier.verify()

    if args.online_check:
        output_file = args.output or "verification_needed.json"
        with open(output_file, "w", encoding="utf-8") as handle:
            json.dump(result["needs_online_check"], handle, indent=2, ensure_ascii=False)
        print(f"Exported {len(result['needs_online_check'])} entries to {output_file}")
    elif args.json:
        print(json.dumps(result, indent=2, ensure_ascii=False))
    elif args.output:
        with open(args.output, "w", encoding="utf-8") as handle:
            json.dump(result, handle, indent=2, ensure_ascii=False)
        print(f"Saved verification result to {args.output}")
    else:
        print(verifier.generate_report(result))

    # Exit policy: PASS/WARNING -> 0, FAIL/error -> 1
    return 1 if result["status"] == "FAIL" else 0


if __name__ == "__main__":
    sys.exit(main())
